// `languageForPath` 的回归护栏。
//
// 它出过一次静默回归: 场景判据写成了 `path.includes('/game/scene/')`, 只认绝对路径; 而差异选项卡
// 传进来的是 git 的**仓库相对路径** (`game/scene/1.txt`, 没有前导斜杠)。于是场景差异被当成
// `plaintext`, 两侧一个字都不着色 —— 没有报错, 类型检查与实机在别处都正常。
//
// 因此这里把两种路径形态都钉住: 判据必须同时认绝对路径与仓库相对路径。

import { describe, expect, it } from 'vitest';

import { LANGUAGE_ID, languageForPath } from '../src/lsp/language';

describe('languageForPath', () => {
  it('认绝对路径下的场景文件', () => {
    expect(languageForPath('C:\\proj\\game\\scene\\1.txt')).toBe(LANGUAGE_ID);
    expect(languageForPath('C:/proj/game/scene/1.txt')).toBe(LANGUAGE_ID);
    expect(languageForPath('/home/me/proj/game/scene/1.txt')).toBe(LANGUAGE_ID);
  });

  it('也认 git 的仓库相对路径 (没有前导斜杠)', () => {
    expect(languageForPath('game/scene/1.txt')).toBe(LANGUAGE_ID);
    expect(languageForPath('game/scene/chapter/2.txt')).toBe(LANGUAGE_ID);
  });

  it('场景目录之外的 .txt 仍是纯文本', () => {
    expect(languageForPath('game/scene-not/1.txt')).toBe('plaintext');
    expect(languageForPath('game/config.txt')).toBe('plaintext');
    expect(languageForPath('notes.txt')).toBe('plaintext');
  });

  it('其它扩展名照旧', () => {
    // 注意: `game/scene/` 之下的任何文件都按场景脚本处理 (判据先行), 所以 json 用例放在别处
    expect(languageForPath('game/config/x.json')).toBe('json');
    expect(languageForPath('game/scene/x.json')).toBe(LANGUAGE_ID);
    expect(languageForPath('a/b.ts')).toBe('typescript');
    expect(languageForPath('a/b.css')).toBe('css');
    expect(languageForPath('a/b.md')).toBe('markdown');
    expect(languageForPath('C:\\proj\\game\\scene\\background.png')).toBe(LANGUAGE_ID);
  });
});
